    <script type="text/babel">
        class App extends React.Component {
            constructor(props) {
                super(props);
                this.state = {
                    items: [],
                    loading: false,
                    page: 1,
                    totalPages: 0,
                    searchQuery: '',
                    sortBy: 'newest'
                };
            }

            componentDidMount() {
                this.fetchItems();
            }

            fetchItems = async () => {
                this.setState({ loading: true });
                try {
                    const response = await fetch(`/api/items?page=${this.state.page}&search=${this.state.searchQuery}&sort=${this.state.sortBy}`);
                    const data = await response.json();
                    this.setState({
                        items: data.items,
                        totalPages: data.totalPages,
                        loading: false
                    });
                } catch (error) {
                    console.error('Error fetching items:', error);
                    this.setState({ loading: false });
                }
            }

            handleSearch = (event) => {
                this.setState({ searchQuery: event.target.value }, () => {
                    this.fetchItems();
                });
            }

            handleSort = (sortBy) => {
                this.setState({ sortBy }, () => {
                    this.fetchItems();
                });
            }

            handlePageChange = (newPage) => {
                this.setState({ page: newPage }, () => {
                    this.fetchItems();
                });
            }

            render() {
                const { items, loading, page, totalPages, searchQuery, sortBy } = this.state;
                return (
                    <div className="app">
                        <h1>Items List</h1>
                        <div className="controls">
                            <input
                                type="text"
                                placeholder="Search..."
                                value={searchQuery}
                                onChange={this.handleSearch}
                            />
                            <select value={sortBy} onChange={(e) => this.handleSort(e.target.value)}>
                                <option value="newest">Newest</option>
                                <option value="oldest">Oldest</option>
                                <option value="name">Name</option>
                            </select>
                        </div>
                        {loading ? (
                            <div className="loading">Loading...</div>
                        ) : (
                            <div className="items">
                                {items.map(item => (
                                    <div key={item.id} className="item">
                                        <h3>{item.name}</h3>
                                        <p>{item.description}</p>
                                    </div>
                                ))}
                            </div>
                        )}
                        <div className="pagination">
                            {Array.from({ length: totalPages }, (_, i) => i + 1).map(p => (
                                <button
                                    key={p}
                                    className={p === page ? 'active' : ''}
                                    onClick={() => this.handlePageChange(p)}
                                >
                                    {p}
                                </button>
                            ))}
                        </div>
                    </div>
                );
            }
        }

        ReactDOM.render(<App />, document.getElementById('root'));
    </script>
